// Developer tests for slice 45 (the review and retrofit): owner-supplied
// evidence judged by magic bytes and size, never decoded; the CLI's review
// and verdicts commands parsed; a review file's closed schema and its
// evidence; the at_alpha notices; the retrofit map's `shape: "unknown"`,
// admitted only in an adopted project and never refused by clause 5.
// Against generated bytes only; nothing is decoded or run.

import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { dirname, join } from 'node:path';
import { test } from 'node:test';
import { fileURLToPath } from 'node:url';

const dist = join(dirname(fileURLToPath(import.meta.url)), '..', '..', 'dist');
const { checkEvidence, formatOfBytes, formatOfName, validName } = await import(join(dist, 'design', 'evidence.js'));
const { parseDesignCommand, parseDesignVerdicts } = await import(join(dist, 'design', 'design-command.js'));
const { checkDesign, gitBlobId } = await import(join(dist, 'design', 'check.js'));
const { parseModuleMap } = await import(join(dist, 'plan', 'schemas.js'));
const { interfaceShapesMissing } = await import(join(dist, 'plan', 'check.js'));

const PNG = Buffer.concat([Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]), Buffer.alloc(24)]);
const WEBP = Buffer.concat([Buffer.from('RIFF'), Buffer.alloc(4), Buffer.from('WEBP'), Buffer.alloc(8)]);
const JPEG = Buffer.from([0xff, 0xd8, 0xff, 0xe0, 0, 16, 0x4a, 0x46, 0x49, 0x46, 0, 1, 1, 0, 0, 1, 0, 1, 0, 0, 0xff, 0xd9]);
const MP4 = Buffer.concat([Buffer.from([0, 0, 0, 16]), Buffer.from('ftypisom'), Buffer.alloc(4)]);
const webm = (doc) => {
  const body = Buffer.concat([Buffer.from([0x42, 0x82, 0x80 | doc.length]), Buffer.from(doc)]);
  return Buffer.concat([Buffer.from([0x1a, 0x45, 0xdf, 0xa3, 0x80 | body.length]), body]);
};

test('evidence formats by magic bytes, names by extension; a contradiction refused, nothing decoded', () => {
  assert.deepEqual([PNG, WEBP, JPEG, MP4, webm('webm')].map(formatOfBytes), ['png', 'webp', 'jpeg', 'mp4', 'webm']);
  assert.equal(formatOfBytes(webm('matroska')), null, 'an EBML file that is not WebM');
  assert.equal(formatOfBytes(Buffer.from('<svg/>')), null);
  assert.deepEqual(['a.png', 'b.JPG', 'c.jpeg', 'd.webm', 'e.mp4', 'f.gif', 'g'].map(formatOfName), ['png', 'jpeg', 'jpeg', 'webm', 'mp4', null, null]);
  const ok = checkEvidence([{ name: 'a.png', bytes: PNG }, { name: 'b.webm', bytes: webm('webm') }], { file: 1024, review: 4096 });
  assert.equal(ok.ok, true);
  assert.deepEqual(ok.files.map((f) => [f.format, f.digest]), [
    ['png', `sha256:${createHash('sha256').update(PNG).digest('hex')}`],
    ['webm', `sha256:${createHash('sha256').update(webm('webm')).digest('hex')}`],
  ]);
  const lying = checkEvidence([{ name: 'shot.jpg', bytes: PNG }], { file: 1024, review: 4096 });
  assert.equal(lying.ok, false);
  assert.equal(lying.reasons[0].code, 'REVIEW_EVIDENCE_INVALID');
  assert.equal(lying.reasons[0].subjects.file, 'shot.jpg');
});

test('evidence bounds per file and per review, each naming its key', () => {
  const big = checkEvidence([{ name: 'big.png', bytes: Buffer.concat([PNG, Buffer.alloc(2000)]) }], { file: 1024, review: 1 << 20 });
  assert.equal(big.ok, false);
  assert.ok(big.reasons.some((r) => r.subjects.file === 'big.png' && r.subjects.key === 'design_review_evidence_max_bytes'));
  const together = checkEvidence(
    [1, 2, 3].map((i) => ({ name: `p${i}.png`, bytes: Buffer.concat([PNG, Buffer.alloc(600)]) })),
    { file: 1024, review: 1500 },
  );
  assert.equal(together.ok, false);
  assert.ok(together.reasons.some((r) => r.subjects.key === 'design_review_evidence_max_review_bytes'));
  assert.equal(validName('a.png'), true);
  for (const bad of ['', '../a.png', 'x/a.png', 'a\u0000.png', '.', '..']) assert.equal(validName(bad), false, JSON.stringify(bad));
});

test('surety design review: --evidence takes the rest; a missing file is a usage error', () => {
  const r = parseDesignCommand(['review', '--project', 'prj_1', '--target', 'android', '--build', '1.4.2 (37)', '--candidate', 'cand_1', '--observed-on', 'device']);
  assert.equal(r.method, 'POST');
  assert.equal(r.path, '/v1/projects/prj_1/design/reviews');
  assert.deepEqual(r.body, { target: 'android', build_ref: '1.4.2 (37)', candidate: 'cand_1', observed_on: 'device' });
  assert.match(parseDesignCommand(['review', '--project', 'prj_1', '--target', 'android']), /--build/);
  assert.match(parseDesignCommand(['review', '--project', 'prj_1', '--target', 'android', '--build', 'b', '--evidence', '/nonexistent/x.png']), /could not read/);
});

test('surety design verdicts: confirm with edits, strikes and a severity; reject takes none', () => {
  const c = parseDesignVerdicts(['--project', 'prj_1', 'drv_1', 'confirm', '--edit', '{"target":"web","screen":"S1","observed_on":"emulator"}', '--strike', 'web/S3', '--severity', 'high']);
  assert.deepEqual(c, { project: 'prj_1', review: 'drv_1', answer: { option: 'confirm', edits: [{ target: 'web', screen: 'S1', observed_on: 'emulator' }], strikes: [{ target: 'web', screen: 'S3' }], severity: 'high' } });
  assert.deepEqual(parseDesignVerdicts(['--project', 'prj_1', 'drv_1', 'reject']), { project: 'prj_1', review: 'drv_1', answer: { option: 'reject' } });
  assert.match(parseDesignVerdicts(['--project', 'prj_1', 'drv_1', 'reject', '--strike', 'web/S1']), /no --edit/);
  assert.match(parseDesignVerdicts(['--project', 'prj_1', 'drv_1', 'maybe']), /confirm\|reject/);
  assert.match(parseDesignVerdicts(['--project', 'prj_1', 'drv_1', 'confirm', '--edit', 'not json']), /JSON/);
});

// The smallest tree the check reads beside a review file: the reasons a
// review file adds are what the cases compare.
const reviewReasons = (review, ctx = {}) => {
  const files = new Map([['reviews/review-1.json', Buffer.from(JSON.stringify(review))]]);
  return checkDesign({ files }, { inventory: null, externalHosts: [], approved: [], ...ctx }).reasons.filter((r) => String(r.subjects.file ?? '').startsWith('reviews/'));
};
const REVIEW = { subject: { kind: 'owner_build', target: 'android', build_ref: 'b' }, screens: [{ target: 'android', key: 'S2', verdict: 'matches', observed_on: 'device', evidence: [], deltas: [] }], revised_design: false, first_design: false };

test('B.14: a review file is closed, a verdict never carries a status, and cites only its own evidence', () => {
  assert.deepEqual(reviewReasons(REVIEW), []);
  const forged = reviewReasons({ ...REVIEW, screens: [{ ...REVIEW.screens[0], status: 'confirmed' }] });
  assert.ok(forged.some((r) => r.code === 'DESIGN_SCHEMA_INVALID' && JSON.stringify(r.subjects).includes('status')));
  assert.ok(reviewReasons({ ...REVIEW, screens: [{ ...REVIEW.screens[0], verdict: 'differs' }] }).some((r) => r.subjects.field === 'screens[0].verdict'));
  assert.ok(reviewReasons({ ...REVIEW, screens: [{ ...REVIEW.screens[0], deltas: [{ owner_words: 'x', kind: 'cosmetic' }] }] }).some((r) => r.subjects.field === 'screens[0].deltas[0].kind'));
  const cites = { ...REVIEW, screens: [{ ...REVIEW.screens[0], evidence: ['dev_1'] }] };
  assert.ok(reviewReasons(cites, { reviews: { held: {}, run: [] } }).some((r) => /dev_1 is not evidence this review holds/.test(r.subjects.why)));
  assert.deepEqual(reviewReasons(cites, { reviews: { held: {}, run: ['dev_1'] } }), []);
  // A recorded review's file is judged against that review's own evidence.
  const blob = gitBlobId(Buffer.from(JSON.stringify(cites)));
  assert.deepEqual(reviewReasons(cites, { reviews: { held: { [blob]: ['dev_1'] }, run: [] } }), []);
});

test('git blob ids as git computes them', () => {
  // `printf 'hello\n' | git hash-object --stdin`
  assert.equal(gitBlobId(Buffer.from('hello\n')), 'ce013625030ba8dba906f756967f9e9ca394464a');
});

test('at_alpha shows a convention the code does not show and an unshaped interface; before_build refuses them', () => {
  const inventory = { inventory_digest: 'd', targets: [{ module: 'web', target: 'web', ui_technology: 'html_css', layouts: [], required_conventions: ['browser_back'], permissions: [], preview_capability: 'native', required_slots: [] }], ui_requirements: [], interfaces: [{ name: 'feed', module: 'service', kind: 'http', errors: [], shape_known: false }], obligations: [], fixtures: [] };
  const screens = { screens: [{ key: 'S1', target: 'web', title: 't', flow_steps: [], requirements: [], interfaces: ['feed'], states: [], layouts: [], inputs: [], conventions: { route: '/', browser_back: 'unknown' } }] };
  const files = new Map([['screens.json', Buffer.from(JSON.stringify(screens))]]);
  const codes = (policy) => {
    const out = checkDesign({ files }, { inventory, externalHosts: [], approved: [], policy });
    return { reasons: out.reasons.map((r) => r.code), notices: out.notices.map((r) => r.code) };
  };
  const before = codes('before_build');
  assert.ok(before.reasons.includes('DESIGN_CONVENTION_UNKNOWN') && before.reasons.includes('DESIGN_INTERFACE_SHAPE_UNKNOWN'));
  assert.deepEqual(before.notices, []);
  const alpha = codes('at_alpha');
  assert.ok(!alpha.reasons.includes('DESIGN_CONVENTION_UNKNOWN') && !alpha.reasons.includes('DESIGN_INTERFACE_SHAPE_UNKNOWN'));
  assert.deepEqual(alpha.notices.sort(), ['DESIGN_CONVENTION_UNKNOWN', 'DESIGN_INTERFACE_SHAPE_UNKNOWN']);
});

const MAP = (iface) =>
  JSON.stringify({
    version: 1,
    modules: [
      { name: 'service', paths: ['server.mjs'], sensitive_areas: [], surface: 'api', interfaces: [iface] },
      { name: 'web', paths: ['web/'], sensitive_areas: [], surface: 'ui', targets: [{ target: 'web', ui_technology: 'html_css' }], interfaces: [] },
    ],
    mapping_from_spec: [],
  });
const FEED = { name: 'feed', kind: 'http', path: '/history', description: 'not visible in the code', consumed_by: ['web'], shape: 'unknown' };

test('shape "unknown": only in an adopted project\'s map, in place of the shapes, and never ARCH_INTERFACE_SHAPE_MISSING', () => {
  const plain = parseModuleMap(MAP(FEED));
  assert.equal(plain.ok, false);
  assert.match(plain.finding.why, /"shape" is not a field/);
  const adopted = parseModuleMap(MAP(FEED), undefined, { adopted: true });
  assert.equal(adopted.ok, true);
  assert.equal(adopted.value.modules[0].interfaces[0].shape, 'unknown');
  assert.deepEqual(interfaceShapesMissing(adopted.value), []);
  const withShape = parseModuleMap(MAP({ ...FEED, response: { type: 'object' } }), undefined, { adopted: true });
  assert.equal(withShape.ok, false);
  assert.match(withShape.finding.why, /carries no response/);
  assert.equal(parseModuleMap(MAP({ ...FEED, shape: 'partial' }), undefined, { adopted: true }).ok, false);
  const { shape: _s, ...unshaped } = FEED;
  assert.deepEqual(interfaceShapesMissing(parseModuleMap(MAP(unshaped)).value), ['service:feed'], 'an interface with no shapes and no declaration is still refused');
});
